content:
:root{
  --or:#F27A1A;--or2:#FF8C38;--or-dim:#FFF4E8;
  --dark:#1A1A1A;--dark2:#2D2D2D;
  --white:#fff;--bg:#FAFAFA;--bg2:#F4F4F6;
  --border:#E8E8EC;--border2:#D4D4DC;
  --text:#1A1A1A;--t2:#555560;--t3:#9898A8;
  --green:#16A34A;--gbg:#F0FDF4;--gbr:#BBF7D0;
  --red:#DC2626;--rbg:#FEF2F2;--rbr:#FECACA;
  --yellow:#D97706;--ybg:#FFFBEB;
  --blue:#2563EB;--bbg:#EFF6FF;
  --r:16px;--r2:12px;--r3:8px;--r4:999px;
  --sh:0 2px 20px rgba(0,0,0,.06);
  --sh2:0 8px 40px rgba(0,0,0,.12);
}
*{box-sizing:border-box;margin:0;padding:0}
html{overflow-x:clip;max-width:100vw}
body{overflow-x:clip;max-width:100vw}
html{scroll-behavior:smooth}
body{font-family:'Inter',sans-serif;background:var(--white);color:var(--text);-webkit-font-smoothing:antialiased}

/* ── NAV ── */
/* SADECE sayfa ust menusu — 'body >' olmazsa kenar cubugundaki <nav> da etkilenir */
body > nav{
  position:sticky;top:16px;z-index:200;
  padding:0 2rem;
  pointer-events:none;
}
.nav-inner{
  max-width:1200px;margin:0 auto;
  background:rgba(255,255,255,.55);
  backdrop-filter:blur(26px) saturate(1.7);
  -webkit-backdrop-filter:blur(26px) saturate(1.7);
  border:1px solid rgba(255,255,255,.55);
  border-radius:100px;
  height:62px;
  display:flex;align-items:center;justify-content:space-between;
  padding:0 1.5rem;
  box-shadow:0 8px 32px rgba(20,17,14,.12),0 1px 0 rgba(255,255,255,.6) inset;
  pointer-events:all;
}
.logo{display:flex;align-items:center;gap:10px;text-decoration:none}
.logo-icon{
  width:36px;height:36px;border-radius:50%;
  background:var(--or);
  display:flex;align-items:center;justify-content:center;
  font-size:16px;font-weight:900;color:#fff;
}
.logo-text{font-size:17px;font-weight:800;color:var(--dark);letter-spacing:-.4px}
.logo-text em{color:var(--or);font-style:normal}
.nav-center{display:flex;gap:2px}
.nav-link{
  padding:7px 14px;border-radius:50px;
  font-size:14px;font-weight:500;color:#555;
  cursor:pointer;border:none;background:transparent;
  font-family:'Inter',sans-serif;transition:all .15s;text-decoration:none;
  white-space:nowrap;
}
.nav-link:hover{color:var(--dark);background:rgba(0,0,0,.05)}
.nav-right{display:flex;align-items:center;gap:8px}
.btn-dark{
  background:var(--dark);color:#fff;border:none;
  padding:10px 22px;border-radius:var(--r4);
  font-size:15px;font-weight:700;cursor:pointer;
  font-family:'Inter',sans-serif;transition:all .15s;
  display:flex;align-items:center;gap:6px;
}
.btn-dark:hover{background:var(--dark2);transform:translateY(-1px)}
.btn-outline-nav{
  background:transparent;border:1.5px solid var(--border2);color:var(--text);
  padding:9px 18px;border-radius:var(--r4);
  font-size:15px;font-weight:600;cursor:pointer;
  font-family:'Inter',sans-serif;transition:all .15s;
}
.btn-outline-nav:hover{border-color:var(--or);color:var(--or)}
.user-pill{
  display:flex;align-items:center;gap:8px;
  padding:5px 14px 5px 6px;
  background:var(--bg2);border-radius:var(--r4);border:1px solid var(--border);
}
.user-avatar{
  width:28px;height:28px;border-radius:50%;
  background:var(--or);
  display:flex;align-items:center;justify-content:center;
  font-size:12px;font-weight:800;color:#fff;
}
.user-name{font-size:13px;font-weight:600;color:var(--text)}
.btn-logout-sm{
  background:transparent;border:none;color:var(--t3);
  font-size:12px;cursor:pointer;padding:0;font-family:'Inter',sans-serif;
  transition:color .15s;
}
.btn-logout-sm:hover{color:var(--red)}

/* ── HERO ── */
.hero{
  min-height:calc(100vh - 80px);
  display:flex;align-items:center;justify-content:center;
  text-align:center;
  padding:6rem 2rem 4rem;
  position:relative;overflow:hidden;
  background:linear-gradient(135deg,#FFF0EB 0%,#FFF8F5 30%,#F8F4FF 60%,#EEF4FF 100%);
}
.hero-blob1{
  position:absolute;top:-100px;left:-100px;
  width:500px;height:500px;border-radius:50%;
  background:radial-gradient(circle,rgba(242,122,26,.12) 0%,transparent 70%);
  pointer-events:none;
}
.hero-blob2{
  position:absolute;bottom:-80px;right:-80px;
  width:400px;height:400px;border-radius:50%;
  background:radial-gradient(circle,rgba(99,102,241,.1) 0%,transparent 70%);
  pointer-events:none;
}
.hero-tag{
  display:inline-flex;align-items:center;gap:8px;
  background:var(--dark);color:#fff;
  font-size:11px;font-weight:700;
  padding:5px 14px;border-radius:var(--r4);
  margin-bottom:1.75rem;letter-spacing:.04em;
}
.hero-tag span{background:var(--or);color:#fff;padding:2px 8px;border-radius:20px;font-size:10px}
.hero h1{
  font-size:clamp(42px,6vw,82px);
  font-weight:900;color:var(--dark);
  letter-spacing:-3px;line-height:1.04;
  margin-bottom:1.5rem;max-width:860px;
}
.hero-sub{
  font-size:18px;color:#555;line-height:1.7;
  max-width:520px;margin:0 auto 2.5rem;font-weight:400;
}
.hero-btns{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}
.btn-hero-dark{
  background:#111;color:#fff;border:none;
  padding:16px 32px;border-radius:50px;
  font-size:16px;font-weight:700;cursor:pointer;
  font-family:'Inter',sans-serif;transition:all .2s;
  display:flex;align-items:center;gap:8px;
  letter-spacing:-.3px;
}
.btn-hero-dark:hover{background:#222;transform:translateY(-2px);box-shadow:0 12px 32px rgba(0,0,0,.25)}
.btn-hero-outline{
  background:#fff;color:#111;border:1.5px solid #ddd;
  padding:15px 28px;border-radius:50px;
  font-size:16px;font-weight:600;cursor:pointer;
  font-family:'Inter',sans-serif;transition:all .2s;
  letter-spacing:-.2px;
}
.btn-hero-outline:hover{border-color:#111;transform:translateY(-2px);box-shadow:0 6px 20px rgba(0,0,0,.1)}
.hero-stats{
  display:flex;justify-content:center;gap:2.5rem;margin-top:3.5rem;
  flex-wrap:wrap;padding-top:2rem;border-top:1px solid rgba(0,0,0,.06);max-width:520px;margin-left:auto;margin-right:auto;
}
.hero-stat-val{font-size:26px;font-weight:900;color:var(--dark);letter-spacing:-1px}
.hero-stat-label{font-size:12px;color:#999;margin-top:3px;font-weight:500}

/* ── HOW IT WORKS ── */
.how-section{
  padding:5rem 2rem;
  background:var(--white);
}
.section-inner{max-width:1100px;margin:0 auto}
.section-tag{
  font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:var(--or);margin-bottom:.75rem;
}
.section-title{
  font-size:clamp(28px,3.5vw,42px);font-weight:900;
  color:var(--dark);letter-spacing:-1.5px;line-height:1.1;
  margin-bottom:.75rem;
}
.section-sub{font-size:16px;color:var(--t2);line-height:1.6;max-width:480px}
.how-grid{display:grid;grid-template-columns:1fr 1fr;gap:4rem;align-items:center;margin-top:3rem}
.how-steps{display:flex;flex-direction:column;gap:2.5rem}
.how-step{display:flex;gap:1.25rem;align-items:flex-start}
.how-num{
  font-size:13px;font-weight:800;color:var(--or);
  width:36px;flex-shrink:0;padding-top:2px;
}
.how-step-title{font-size:17px;font-weight:800;color:var(--dark);margin-bottom:.4rem;letter-spacing:-.3px}
.how-step-desc{font-size:14px;color:var(--t2);line-height:1.6}
.how-visual{
  background:linear-gradient(135deg,#FFF0EB,#FFF8F5);
  border:1px solid var(--border);border-radius:24px;
  padding:2rem;min-height:320px;
  display:flex;flex-direction:column;gap:12px;justify-content:center;
}
.hv-card{
  background:#fff;border-radius:var(--r);padding:16px 20px;
  box-shadow:var(--sh);border:1px solid var(--border);
  display:flex;align-items:center;gap:14px;
}
.hv-icon{width:40px;height:40px;border-radius:10px;background:var(--or-dim);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0}
.hv-label{font-size:12px;color:var(--t3);margin-bottom:3px}
.hv-val{font-size:17px;font-weight:800;color:var(--dark)}
.hv-val.green{color:var(--green)}
.hv-val.red{color:var(--red)}

/* ── PRICING ── */
.pricing-section{
  padding:5rem 2rem;
  background:linear-gradient(180deg,#FAFAFA 0%,#fff 100%);
}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:3rem}
.price-card{
  background:#fff;border:1.5px solid var(--border);
  border-radius:20px;padding:2rem;
  transition:all .2s;
}
.price-card:hover{transform:translateY(-4px);box-shadow:var(--sh2)}
.price-card.featured{
  background:var(--dark);border-color:var(--dark);
  transform:scale(1.03);
}
.price-card.featured:hover{transform:scale(1.03) translateY(-4px)}
.price-badge{
  display:inline-block;background:var(--or);color:#fff;
  font-size:10px;font-weight:800;padding:3px 10px;
  border-radius:20px;margin-bottom:1rem;letter-spacing:.05em;
}
.price-name{font-size:14px;font-weight:700;color:var(--t2);margin-bottom:.5rem}
.price-card.featured .price-name{color:rgba(255,255,255,.6)}
.price-amount{font-size:42px;font-weight:900;color:var(--dark);letter-spacing:-2px;margin-bottom:.25rem}
.price-card.featured .price-amount{color:#fff}
.price-period{font-size:13px;color:var(--t3);margin-bottom:1.5rem}
.price-card.featured .price-period{color:rgba(255,255,255,.5)}
.price-divider{height:1px;background:var(--border);margin-bottom:1.5rem}
.price-card.featured .price-divider{background:rgba(255,255,255,.15)}
.price-features{display:flex;flex-direction:column;gap:10px;margin-bottom:1.75rem}
.price-feature{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--t2)}
.price-card.featured .price-feature{color:rgba(255,255,255,.75)}
.pf-icon{width:18px;height:18px;border-radius:50%;background:var(--gbg);display:flex;align-items:center;justify-content:center;font-size:9px;flex-shrink:0;border:1px solid var(--gbr)}
.price-card.featured .pf-icon{background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.3)}
.btn-price{
  width:100%;padding:13px;border-radius:var(--r4);
  font-size:14px;font-weight:700;cursor:pointer;
  font-family:'Inter',sans-serif;transition:all .2s;border:none;
  background:var(--dark);color:#fff;
}
.btn-price:hover{opacity:.85}
.price-card.featured .btn-price{background:#fff;color:var(--dark)}
.price-card.featured .btn-price:hover{background:var(--bg2)}

/* ── APP SECTION ── */
.app-wrap{max-width:1160px;margin:0 auto;padding:0 1.5rem 3rem}

/* PAGE TABS */
.page{display:none}
.page.active{display:block}

/* DEMO BANNER */
.demo-banner{
  background:linear-gradient(135deg,var(--dark),var(--dark2));
  border-radius:20px;padding:1.5rem 2rem;
  display:flex;align-items:center;justify-content:space-between;
  gap:1rem;margin-bottom:1.25rem;flex-wrap:wrap;
}
.demo-banner h3{font-size:16px;font-weight:800;color:#fff;margin-bottom:4px}
.demo-banner p{font-size:13px;color:rgba(255,255,255,.5)}
.demo-actions{display:flex;gap:8px;flex-wrap:wrap}

/* BUTTONS */
.btn{
  padding:10px 18px;border-radius:var(--r4);font-size:13px;font-weight:700;
  cursor:pointer;font-family:'Inter',sans-serif;transition:all .15s;
  display:inline-flex;align-items:center;gap:6px;border:none;white-space:nowrap;
}
.btn-primary{background:var(--or);color:#fff}
.btn-primary:hover{background:var(--or2);transform:translateY(-1px)}
.btn-secondary{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);color:#fff}
.btn-secondary:hover{background:rgba(255,255,255,.18)}
.btn-ghost{background:var(--bg2);border:1.5px solid var(--border);color:var(--t2)}
.btn-ghost:hover{border-color:var(--or);color:var(--or);background:var(--or-dim)}

/* CONNECT CARD */
.connect-card{
  background:#fff;border:1.5px solid var(--border);
  border-radius:20px;overflow:hidden;
  box-shadow:var(--sh);margin-bottom:1.25rem;
}
.card-head{
  background:linear-gradient(135deg,var(--dark),var(--dark2));
  padding:1rem 1.5rem;display:flex;align-items:center;gap:10px;
}
.card-head-icon{
  width:36px;height:36px;border-radius:10px;
  background:var(--or);display:flex;align-items:center;
  justify-content:center;font-size:16px;flex-shrink:0;
}
.card-head-title{font-size:15px;font-weight:800;color:#fff}
.card-head-sub{font-size:11px;color:rgba(255,255,255,.45);margin-top:2px}
.card-body{padding:1.5rem}

.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:1.25rem}
.step{background:var(--bg);border:1.5px solid var(--border);border-radius:var(--r2);padding:14px}
.step-num{
  width:28px;height:28px;border-radius:50%;
  background:var(--dark);color:#fff;
  font-size:12px;font-weight:900;
  display:flex;align-items:center;justify-content:center;
  margin-bottom:8px;
}
.step-title{font-size:13px;font-weight:700;color:var(--text);margin-bottom:3px}
.step-desc{font-size:11px;color:var(--t3);line-height:1.5}

.field-grid{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:10px;align-items:flex-end;margin-bottom:10px}
.fg{display:flex;flex-direction:column;gap:5px}
.flabel{font-size:10px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.07em}
.finput{
  width:100%;padding:10px 13px;border:1.5px solid var(--border);
  border-radius:var(--r2);font-size:13px;font-weight:600;
  color:var(--text);background:var(--bg);
  font-family:'Inter',sans-serif;transition:all .15s;
}
.finput:focus{outline:none;border-color:var(--or);background:#fff;box-shadow:0 0 0 3px rgba(242,122,26,.1)}

.status-bar{
  display:flex;align-items:center;gap:10px;
  padding:10px 14px;border-radius:var(--r2);
  background:var(--bg);border:1.5px solid var(--border);
  font-size:13px;margin-bottom:12px;
}
.sdot{width:9px;height:9px;border-radius:50%;background:var(--border2);flex-shrink:0;transition:all .3s}
.sdot.on{background:var(--green);box-shadow:0 0 0 3px rgba(22,163,74,.15)}
.sdot.loading{background:var(--or);animation:blink .8s infinite}
.sdot.err{background:var(--red)}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.3}}
.status-text{font-weight:600;color:var(--text)}
.status-sub{font-size:12px;color:var(--t3);margin-left:auto}

/* TOOLBAR */
.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:1.25rem;flex-wrap:wrap;gap:10px}
.toolbar-left{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.tb-title{font-size:18px;font-weight:900;letter-spacing:-.5px;color:#111}
.count-badge{
  background:rgba(242,122,26,.1);color:var(--or);
  border:1px solid rgba(242,122,26,.2);
  font-size:11px;font-weight:800;padding:3px 12px;border-radius:50px;
}
.filter-bar{display:flex;gap:2px;background:#F3F4F6;border:none;padding:3px;border-radius:50px}
.ftab{
  padding:6px 16px;border-radius:50px;font-size:12px;font-weight:600;
  cursor:pointer;border:none;background:transparent;color:#9CA3AF;
  font-family:'Inter',sans-serif;transition:all .2s;white-space:nowrap;
}
.ftab.active{background:#fff;color:#111;box-shadow:0 2px 8px rgba(0,0,0,.1)}
.search-wrap{position:relative;display:flex;align-items:center}
.search-icon{position:absolute;left:12px;font-size:13px;color:#9CA3AF;pointer-events:none}
.search-inp{
  padding:9px 14px 9px 36px;border:1.5px solid #E5E7EB;
  border-radius:50px;font-size:13px;color:#111;
  background:#fff;font-family:'Inter',sans-serif;width:220px;transition:all .2s;
  box-shadow:0 1px 4px rgba(0,0,0,.04);
}
.search-inp:focus{outline:none;border-color:var(--or);box-shadow:0 0 0 3px rgba(242,122,26,.08)}
.btn-sm{
  padding:8px 16px;border:1.5px solid #E5E7EB;border-radius:50px;
  font-size:12px;font-weight:600;cursor:pointer;color:#555;
  background:#fff;font-family:'Inter',sans-serif;transition:all .2s;
  display:flex;align-items:center;gap:5px;white-space:nowrap;
  box-shadow:0 1px 4px rgba(0,0,0,.04);
}
.btn-sm:hover{border-color:var(--or);color:var(--or);background:#FFFBF5;transform:translateY(-1px)}
.btn-danger-sm{
  padding:8px 16px;border:1.5px solid rgba(239,68,68,.2);border-radius:50px;
  font-size:12px;font-weight:600;cursor:pointer;color:#DC2626;
  background:rgba(239,68,68,.05);font-family:'Inter',sans-serif;transition:all .2s;
  display:flex;align-items:center;gap:5px;white-space:nowrap;
}
.btn-danger-sm:hover{background:#DC2626;color:#fff;border-color:#DC2626;transform:translateY(-1px)}
.cb-wrap{display:flex;align-items:center;justify-content:center}
input[type=checkbox].row-cb{width:16px;height:16px;cursor:pointer;accent-color:var(--or)}
.sel-bar{
  display:none;align-items:center;gap:10px;
  padding:10px 14px;background:var(--or-dim);border:1.5px solid rgba(242,122,26,.2);
  border-radius:var(--r2);margin-bottom:10px;font-size:13px;font-weight:600;color:var(--or);
}
.sel-bar.show{display:flex}

/* PRODUCT TABLE */
.prod-table-wrap{background:#fff;border:1px solid #E5E7EB;border-radius:20px;overflow-x:auto;box-shadow:0 4px 24px rgba(0,0,0,.07)}
.prod-table-wrap table{min-width:1000px}
.ptable{width:100%;border-collapse:collapse;font-size:13px}
.ptable thead tr{background:transparent}
.ptable th{
  padding:13px 14px;text-align:left;
  background:#F8F9FB;
  color:#9CA3AF;font-size:10px;font-weight:700;
  text-transform:uppercase;letter-spacing:.08em;
  border-bottom:1.5px solid #EDEEF1;white-space:nowrap;
}
.ptable th.th-satis{
  background:linear-gradient(135deg,#1A1A2E 0%,#2D2D4E 100%);
  color:rgba(255,255,255,.9);border-bottom:none;
}
.ptable th.th-komisyon{
  background:linear-gradient(135deg,#F27A1A 0%,#FF9A40 100%);
  color:rgba(255,255,255,.95);border-bottom:none;
}
.ptable th.th-alis{
  background:#F8F9FB;color:#9CA3AF;
}
.ptable th.th-kargo{
  background:#F8F9FB;color:#9CA3AF;
}
.ptable td{padding:11px 14px;border-bottom:1px solid #F3F4F6;vertical-align:middle}
.ptable tr:last-child td{border-bottom:none}
.ptable tbody tr:hover td{background:#FAFBFF;transition:background .15s}
.prod-img{width:52px;height:52px;border-radius:14px;object-fit:cover;border:1.5px solid #F0F0F3;box-shadow:0 2px 8px rgba(0,0,0,.08)}
.prod-img-ph{
  width:52px;height:52px;border-radius:14px;
  background:linear-gradient(135deg,#1A1A2E,#2D2D4E);display:flex;align-items:center;
  justify-content:center;font-size:18px;font-weight:800;color:#fff;flex-shrink:0;
}
.prod-name{font-weight:700;color:#111;max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13.5px;letter-spacing:-.1px}
.prod-cat{font-size:11px;color:#B0B7C3;margin-top:4px;font-weight:500}
.price-val{font-weight:800;color:#111;font-size:14px}
.kom-pill{display:inline-flex;background:rgba(242,122,26,.08);color:var(--or);font-size:11px;font-weight:800;padding:3px 10px;border-radius:50px;border:1px solid rgba(242,122,26,.15)}
.kar-badge{display:inline-flex;font-size:13px;font-weight:800;padding:6px 14px;border-radius:50px;letter-spacing:-.2px}
.kb-good{background:rgba(16,185,129,.1);color:#059669;border:1px solid rgba(16,185,129,.2)}
.kb-bad{background:rgba(239,68,68,.08);color:#DC2626;border:1px solid rgba(239,68,68,.15)}
.kb-neutral{background:#F3F4F6;color:#9CA3AF}
.detay-btn{
  padding:9px 15px;border:none;border-radius:50px;
  font-size:12px;font-weight:700;cursor:pointer;
  color:#fff;background:#111;
  font-family:'Inter',sans-serif;transition:all .2s;
  display:flex;align-items:center;gap:5px;white-space:nowrap;
  box-shadow:0 2px 8px rgba(0,0,0,.15);
}
