/* FOOTER */
footer{background:linear-gradient(180deg,#0D1117 0%,#090D13 100%);padding:0;margin-top:4rem;border-top:1px solid rgba(255,255,255,.06)}
.footer-logo-text{font-size:18px;font-weight:800;color:#fff;margin-bottom:.5rem}
.footer-logo-text em{color:var(--or);font-style:normal}
