.spin{width:15px;height:15px;border:2px solid rgba(255,255,255,.25);border-top-color:#fff;border-radius:50%;display:inline-block;animation:rot .6s linear infinite;vertical-align:middle}
@keyframes rot{to{transform:rotate(360deg)}}

/* LOGIN CTA */
.login-cta{
  background:linear-gradient(135deg,#FFF0EB,#FFF8F5);
  border:1.5px solid var(--border);border-radius:20px;
