.kp-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin-bottom:20px}
.kp-card{
  --c:#14110E;--cbg:rgba(20,17,14,.06);
  position:relative;overflow:hidden;padding:20px;border-radius:20px;
  background:linear-gradient(170deg,rgba(255,255,255,.92),rgba(255,255,255,.7));
  border:1px solid rgba(20,17,14,.07);
  box-shadow:0 1px 2px rgba(20,17,14,.03),0 20px 42px -34px rgba(20,17,14,.4);
  transition:transform .25s cubic-bezier(.2,.7,.2,1),box-shadow .25s,border-color .25s;
}
.kp-card::before{
  content:"";position:absolute;top:-40px;right:-40px;width:120px;height:120px;border-radius:50%;
  background:var(--cbg);opacity:.55;transition:transform .35s cubic-bezier(.2,.7,.2,1);
}
.kp-card::after{content:"";position:absolute;left:20px;right:20px;bottom:0;height:3px;border-radius:3px 3px 0 0;background:var(--c);opacity:.55}
.kp-card:hover{transform:translateY(-4px);border-color:rgba(20,17,14,.12);box-shadow:0 28px 54px -30px rgba(20,17,14,.5)}
.kp-card:hover::before{transform:scale(1.25)}
.kp-ic{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:13px;background:var(--cbg);color:var(--c);margin-bottom:16px}
