  font-size:32px;font-weight:800;letter-spacing:-1.4px;color:var(--c);
  line-height:1.02;margin-top:6px;font-variant-numeric:tabular-nums;
}
.kp-sub{position:relative;z-index:1;font-size:11px;color:#A6A6B2;margin-top:6px}

