/* ══════════════════════════════════════════════════════════
   GENEL BAKIŞ KARTLARI — ortalanmış, premium
   ══════════════════════════════════════════════════════════ */
.kp-grid{
  display:grid;grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px;margin-bottom:22px;
}
.kp-card{
  --c:#14110E;--cbg:rgba(20,17,14,.06);
  position:relative;overflow:hidden;isolation:isolate;
  display:flex;flex-direction:column;align-items:center;text-align:center;
  padding:26px 18px 22px;border-radius:22px;
  background:linear-gradient(180deg,rgba(255,255,255,.92),rgba(255,255,255,.66));
  backdrop-filter:blur(20px) saturate(1.3);-webkit-backdrop-filter:blur(20px) saturate(1.3);
  border:1px solid rgba(255,255,255,.85);
  box-shadow:
    0 1px 0 rgba(255,255,255,.95) inset,
    0 1px 2px rgba(20,17,14,.04),
    0 20px 44px -30px rgba(20,17,14,.42);
  transition:transform .3s cubic-bezier(.2,.7,.2,1),box-shadow .3s,border-color .3s;
}
/* ikonun arkasından yükselen yumuşak renk hale */
.kp-card::before{
  content:"";position:absolute;top:-46px;left:50%;transform:translateX(-50%);
  width:190px;height:150px;border-radius:50%;z-index:-1;
  background:var(--cbg);filter:blur(26px);opacity:.9;
  transition:opacity .3s,transform .3s cubic-bezier(.2,.7,.2,1);
}
/* üst kenarda ince ışık çizgisi */
.kp-card::after{
  content:"";position:absolute;top:0;left:22%;right:22%;height:2px;border-radius:0 0 3px 3px;
  background:linear-gradient(90deg,transparent,var(--c),transparent);opacity:.6;
}
.kp-card:hover{
  transform:translateY(-5px);
  border-color:rgba(255,255,255,1);
  box-shadow:
    0 1px 0 rgba(255,255,255,1) inset,
    0 2px 6px rgba(20,17,14,.05),
    0 34px 62px -30px rgba(20,17,14,.5);
}
.kp-card:hover::before{opacity:1;transform:translateX(-50%) translateY(6px) scale(1.06)}

.kp-ic{
  display:flex;align-items:center;justify-content:center;
  width:52px;height:52px;border-radius:17px;margin:0 0 16px;
  background:linear-gradient(160deg,rgba(255,255,255,.9),rgba(255,255,255,.45));
  border:1px solid rgba(255,255,255,.95);
  color:var(--c);
  box-shadow:0 1px 0 rgba(255,255,255,.9) inset,0 8px 18px -10px rgba(20,17,14,.5);
}
.kp-lbl{
  font-size:10.5px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;
  color:#9A948C;
}
.kp-val{
  font-family:'Plus Jakarta Sans',sans-serif;
  font-size:34px;font-weight:800;letter-spacing:-1.6px;line-height:1.04;
  color:var(--c);margin-top:9px;font-variant-numeric:tabular-nums;
}
.kp-sub{
  display:inline-flex;align-items:center;gap:6px;
  font-size:11.5px;color:#A29C94;margin-top:9px;font-weight:600;
}
.kp-sub::before{
  content:"";width:5px;height:5px;border-radius:50%;background:var(--c);opacity:.45;
}

/* veri yokken */
.kp-grid.bos .kp-card{background:linear-gradient(180deg,rgba(255,255,255,.8),rgba(255,255,255,.55))}
.kp-grid.bos .kp-card::before{opacity:.4}
.kp-grid.bos .kp-card::after{opacity:.2}
.kp-grid.bos .kp-val{color:#B8B2A9;letter-spacing:-.5px}
.kp-grid.bos .kp-ic{color:#B8B2A9}
.kp-grid.bos .kp-sub::before{opacity:.25}
.kp-grid.bos .kp-card:hover{transform:translateY(-3px)}

@media(max-width:1500px){.kp-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:900px){.kp-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.kp-grid{grid-template-columns:1fr}.kp-val{font-size:30px}}

/* liste kartları kartlarla uyumlu olsun */
