/* ══ HERO — tam dashboard mockup (referans) ══ */
.hero.khm .khm-hero-wrap{max-width:1480px;padding:66px 56px 40px}
.hero.khm .khm-hero-cols{grid-template-columns:1fr 1.14fr;gap:64px}
.hero.khm h1{font-size:clamp(46px,6vw,82px)}
.hero.khm .khm-lead{max-width:560px}
.hero.khm .khm-stage{perspective:2000px}
.hero.khm .hero-dash{width:820px}
@media(max-width:1360px){
  .hero.khm .hero-dash{width:100%}
  .hero.khm .khm-hero-cols{gap:48px}
}
.hero.khm .hero-dash{
  position:relative;width:680px;max-width:100%;border-radius:20px;overflow:hidden;
  background:linear-gradient(158deg,#221A13,#15110D);border:1px solid rgba(255,255,255,.09);
  box-shadow:0 58px 120px -44px rgba(0,0,0,.92),0 0 0 1px rgba(242,122,26,.06) inset;
  transform:rotateY(-15deg) rotateX(5deg);transform-origin:center left;
  animation:heroDashFloat 8s ease-in-out infinite;will-change:transform;
}
@keyframes heroDashFloat{0%,100%{transform:rotateY(-15deg) rotateX(5deg) translateY(0)}50%{transform:rotateY(-12.5deg) rotateX(4deg) translateY(-14px)}}
.hero.khm .hero-dash:hover{animation-play-state:paused}
.hero.khm .hd-donut{
  width:98px;height:98px;border-radius:50%;flex-shrink:0;
  -webkit-mask:radial-gradient(circle 31px at 50% 50%,transparent 31px,#000 32px);
  mask:radial-gradient(circle 31px at 50% 50%,transparent 31px,#000 32px);
}
.hero.khm .hero-alert{
  position:absolute;right:-26px;bottom:8%;width:212px;padding:16px 17px;border-radius:16px;z-index:3;
  background:linear-gradient(160deg,#2A1714,#181110);border:1px solid rgba(251,107,102,.3);
  box-shadow:0 28px 56px rgba(0,0,0,.62);animation:khmFloatB 6.5s ease-in-out infinite;
}
.hero.khm .hd-bar{flex:1;min-width:0;display:flex;align-items:flex-end;justify-content:center;height:100%}
.hero.khm .hd-bar span{width:100%;max-width:11px;border-radius:3px 3px 1px 1px}

/* ── HERO mockup premium efektleri ── */
.hero.khm .hero-dash{transition:transform .55s cubic-bezier(.2,.7,.2,1)}
.hero.khm .hero-dash:hover{animation-play-state:paused;transform:rotateY(-6deg) rotateX(2deg) translateY(-6px)}
/* arkada nabız gibi turuncu ışıma */
.hero.khm .khm-stage::before{
  content:"";position:absolute;inset:-10% 0% -12% 6%;z-index:-1;border-radius:44px;
  background:radial-gradient(closest-side,rgba(242,122,26,.32),transparent 72%);
  filter:blur(36px);animation:hdGlow 5.5s ease-in-out infinite;pointer-events:none;
}
@keyframes hdGlow{0%,100%{opacity:.6;transform:scale(.96)}50%{opacity:1;transform:scale(1.04)}}
/* tablo satırları sırayla canlanır (canlı veri hissi) */
.hero.khm .hd-trow{position:relative}
.hero.khm .hd-trow::before{
  content:"";position:absolute;inset:0;border-radius:6px;pointer-events:none;opacity:0;
  background:linear-gradient(90deg,rgba(242,122,26,.16),rgba(242,122,26,.03) 55%,transparent 78%);
  box-shadow:inset 2px 0 0 #FF9A42;animation:hdRowScan 4.8s ease-in-out infinite;
}
.hero.khm .hd-trow:nth-child(2)::before{animation-delay:0s}
.hero.khm .hd-trow:nth-child(3)::before{animation-delay:.5s}
.hero.khm .hd-trow:nth-child(4)::before{animation-delay:1s}
@keyframes hdRowScan{0%{opacity:0}5%{opacity:1}17%{opacity:0}100%{opacity:0}}
/* yükselişte büyüyen çubuklar */
.hero.khm .hd-bar span{transform-origin:bottom;animation:hdBarGrow .9s cubic-bezier(.2,.8,.2,1) both}
.hero.khm .hd-bar:nth-child(1) span{animation-delay:.05s}
.hero.khm .hd-bar:nth-child(2) span{animation-delay:.11s}
.hero.khm .hd-bar:nth-child(3) span{animation-delay:.17s}
.hero.khm .hd-bar:nth-child(4) span{animation-delay:.23s}
.hero.khm .hd-bar:nth-child(5) span{animation-delay:.29s}
.hero.khm .hd-bar:nth-child(6) span{animation-delay:.35s}
.hero.khm .hd-bar:nth-child(7) span{animation-delay:.41s}
.hero.khm .hd-bar:nth-child(8) span{animation-delay:.47s}
.hero.khm .hd-bar:nth-child(9) span{animation-delay:.53s}
.hero.khm .hd-bar:nth-child(10) span{animation-delay:.59s}
.hero.khm .hd-bar:nth-child(11) span{animation-delay:.65s}
.hero.khm .hd-bar:nth-child(12) span{animation-delay:.71s}
@keyframes hdBarGrow{from{transform:scaleY(0)}to{transform:scaleY(1)}}

/* ══ HERO: Ürün Kâr Tablosu + Excel düşme animasyonu ══ */
.hero.khm #khm-dashcard{
  width:680px;max-width:100%;background:linear-gradient(180deg,#FCFAF6,#F5EFE6);
  border:1px solid rgba(0,0,0,.06);border-radius:22px;overflow:hidden;
