.hero.khm .pk-badge{display:inline-flex;align-items:center;gap:6px;font-size:10px;font-weight:800;color:#0E9E63;background:rgba(52,211,153,.14);border:1px solid rgba(52,211,153,.28);padding:5px 10px;border-radius:20px}
.hero.khm .pk-badge b{width:6px;height:6px;border-radius:50%;background:#12B76A;animation:pkPulse 1.4s ease infinite}
@keyframes pkPulse{0%,100%{opacity:1;box-shadow:0 0 0 0 rgba(18,183,106,.5)}50%{opacity:.7;box-shadow:0 0 0 4px rgba(18,183,106,0)}}
.hero.khm .pk-rows{padding:9px 12px 14px;display:flex;flex-direction:column;gap:8px;position:relative}

