@keyframes pkDashPhase{0%{opacity:0;transform:scale(.985)}5%{opacity:1;transform:scale(1)}30%{opacity:1;transform:scale(1)}36%{opacity:0;transform:scale(.96) translateY(-10px)}100%{opacity:0}}
