.hero.khm .pkd-charts{display:grid;grid-template-columns:1.5fr 1fr;gap:8px;flex:1}
.hero.khm .pkd-card{background:#fff;border:1px solid rgba(0,0,0,.05);border-radius:13px;padding:11px 12px;box-shadow:0 5px 14px -11px rgba(0,0,0,.45);display:flex;flex-direction:column}
.hero.khm .pkd-h{font-size:10px;font-weight:800;color:#7C6E5C;letter-spacing:-.1px}
.hero.khm .pkd-bars{display:flex;align-items:flex-end;gap:5px;flex:1;min-height:74px;margin-top:9px}
